NOTES=[
N('"I play tennis." → He said he ___ tennis.','played','Present Simple → Past Simple: play → played.',{'playing': 'Yalın fiilin yerine -ing gelmez; Present Simple aktarmada Past Simple olur.', 'play': 'Aktarma fiili said geçmişte olduğu için fiil bir kademe geri gider: play → played.'}),
N('"I am working." → She said she ___ working.','was','Present Continuous → Past Continuous: am → was.',{'were': 'were çoğul özneyle kullanılır; she ile was gerekir.', 'been': 'been yardımcı fiil olarak tek başına kullanılmaz; am → was olur.'}),
N('"I will call you tomorrow." → He said he would call me ___.','the following day','tomorrow → the next day / the following day.',{'yesterday': 'yesterday geçmiştir; gelecek bir gün için kullanılmaz.', 'the day before': 'the day before "bir gün önce" demektir; tomorrow → the following day olur.'}),
N('"I am here now." → She said she was there ___.','then','now → then; here → there.',{'now': 'now aktarmada then olur; geçmişteki bir anı anlatırken now kullanılmaz.', 'here': 'here yer belirtir; zaman boşluğuna uymaz.'}),
N('"Do you like pizza?" → She asked me ___ I liked pizza.','if','Evet/hayır sorusu: asked + if / whether.',{'that': 'Evet/hayır sorusu aktarılırken that değil if ya da whether kullanılır.', 'what': 'what soru sözcüğüdür; evet/hayır sorusunda kullanılmaz.'}),
N('"Sit down." → The teacher told us ___ down.','to sit','Emir: told + kişi + to + yalın fiil.',{'sit': 'told + kişi + to + yalın fiil gerekir; to eksik.', 'sitting': 'Emir aktarımında -ing değil to + yalın fiil gelir.'}),
N('"I saw her last week." → He said he had seen her ___.','the week before','last week → the week before.',{'the next week': 'the next week gelecek haftadır; geçmişteki bir haftayı anlatmak için the week before gerekir.', 'the week after': 'the week after "bir sonraki hafta" demektir; last week → the week before olur.'}),
N('"I have finished." → He said he ___ finished.','had','Present Perfect → Past Perfect: have finished → had finished.',{'having': 'having tek başına yardımcı fiil olamaz; Present Perfect aktarmada Past Perfect olur.', 'been': 'been ile finished birleşince anlam bozulur; have → had gerekir.'}),
N('"I can help you." → She said she ___ help me.','could','can → could.',{'could to': 'Modalden sonra to gelmez; could + yalın fiil.', 'was able': 'was able to + yalın fiil gerekir; to olmadan olmaz.'}),
N('"What time is it?" → He asked what time ___.','it was','Aktarılan soru: soru sözcüğü + özne + fiil (zaman bir geri).',{'was it': 'Aktarılan soruda düz cümle sırası kullanılır; özne fiilden önce gelir.', 'is it': 'Hem soru sırası yanlış hem de zaman kaymamış; it was gerekir.'}),
N('"Where did you go?" → She asked where I ___.','had gone','Past Simple soru → Past Perfect: did go → had gone.',{'did go': 'Aktarılan soruda did kullanılmaz; Past Simple → Past Perfect olur.', 'go': 'Zaman kayması yok ve geçmiş anlam kaybolmuş; had gone gerekir.'}),
N('"Can you swim?" → He asked me ___ I could swim.','whether','Evet/hayır sorusu: whether / if.',{'what': 'what bir nesne sorar; evet/hayır sorusunda kullanılmaz.', 'which': 'which seçenek sorar; evet/hayır sorusunda kullanılmaz.'}),
N('"Please wait here." → She asked me ___ there.','to wait','Rica: asked + kişi + to + yalın fiil.',{'waiting': 'ask + kişi + to + yalın fiil kalıbı gerekir; -ing gelmez.', 'for wait': 'for + fiil olmaz; edattan sonra -ing gelir, ama burada to wait gerekir.'}),
N('"Don\'t open the box." → She told him ___ the box.','not to open','Olumsuz emir: told + kişi + not to + yalın fiil.',{"don't open": 'Aktarmada emir kipi korunmaz; not to + yalın fiil olur.', "to don't open": "to ile don't birlikte kullanılmaz; olumsuz biçim not to açılır."}),
N('Hangi cümle doğru?','He asked me where I was going.','Aktarılan soru: düz cümle sırası + zaman kayması.',{'He asked me where was I going.': "Aktarılan soruda düz sıra gerekir; özne was'tan önce gelir.", 'He asked me where I am going to.': 'Zaman kaymamış ve sondaki to fazla; where I was going doğru.'}),
N('Aynı anlamdaki cümle hangisi? → "I will help you," she said.','She said she would help me.','will → would ve zamir değişimi: you → me.',{'She said she would helping me.': 'would + yalın fiil gerekir; -ing eklenmez.', 'She said she will helps me.': 'will ve -s birlikte olmaz; aktarmada will → would olur.'}),
N('"You should see a doctor." → She advised me ___ a doctor.','to see','advise + kişi + to + yalın fiil.',{'see': 'advise + kişi + to + yalın fiil; to gerekir.', 'seeing': 'advise + kişi + -ing kalıbı yoktur; to + yalın fiil gelir.'}),
N('"How old are you?" → He asked me how old I ___.','was','am → was; aktarılan soruda düz sıra.',{'were': 'Özne I olduğu için were değil was gelir.', 'be': 'be yalın hâliyle bu cümlede kullanılmaz; am → was olur.'}),
N('Hangi cümle YANLIŞ?','She asked was I ready.','Aktarılan evet/hayır sorusu if/whether ile başlar, düz sıra kullanılır.',{'She asked if I was ready.': 'Bu cümle doğru: if + özne + was.', 'He said he was tired.': 'Bu cümle doğru: said + Past Simple.'}),
]
